import express, { NextFunction, Request, Response } from "express";
import { TaskManagementService, UserService } from "../application/services";
import { ConflictError, NotFoundError, ValidationError } from "../domain/errors";
import {
  InMemoryProjectRepository,
  InMemoryTaskRepository,
  InMemoryUserRepository,
  UuidGenerator,
} from "./inMemoryRepositories";

function str(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

export function createApp(): express.Express {
  const ids = new UuidGenerator();
  const userRepo = new InMemoryUserRepository();
  const projectRepo = new InMemoryProjectRepository();
  const taskRepo = new InMemoryTaskRepository();
  const userService = new UserService(userRepo, ids);
  const service = new TaskManagementService(projectRepo, taskRepo, userRepo, ids);

  const app = express();
  app.use(express.json());

  app.post("/users", (req: Request, res: Response) => {
    res.status(201).json(userService.create(req.body?.name));
  });

  app.post("/projects", (req: Request, res: Response) => {
    res.status(201).json(service.createProject(req.body?.name));
  });

  app.get("/projects/:projectId", (req: Request, res: Response) => {
    res.json(service.getProject(String(req.params.projectId)));
  });

  app.post("/projects/:projectId/tasks", (req: Request, res: Response) => {
    const body = req.body ?? {};
    const task = service.addTask(String(req.params.projectId), {
      title: body.title,
      description: body.description,
      dueDate: body.dueDate,
      status: body.status,
      assigneeId: body.assigneeId,
    });
    res.status(201).json(task);
  });

  app.get("/projects/:projectId/tasks", (req: Request, res: Response) => {
    const tasks = service.listTasks(String(req.params.projectId), {
      status: str(req.query.status),
      assigneeId: str(req.query.assigneeId),
    });
    res.json(tasks);
  });

  app.put("/tasks/:taskId/assignee", (req: Request, res: Response) => {
    const assigneeId = req.body?.assigneeId;
    if (typeof assigneeId !== "string" || assigneeId === "") {
      throw new ValidationError("assigneeId is required");
    }
    res.json(service.assignTask(String(req.params.taskId), assigneeId));
  });

  app.post("/tasks/:taskId/done", (req: Request, res: Response) => {
    res.json(service.markDone(String(req.params.taskId)));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof ValidationError) {
      res.status(400).json({ error: err.message });
    } else if (err instanceof NotFoundError) {
      res.status(404).json({ error: err.message });
    } else if (err instanceof ConflictError) {
      res.status(409).json({ error: err.message });
    } else if (err instanceof SyntaxError) {
      res.status(400).json({ error: "Invalid JSON body" });
    } else {
      res.status(500).json({ error: "Internal server error" });
    }
  });

  return app;
}

